import{_ as e,o as r,c as o,a6 as s}from"./chunks/framework.CCKCzdWs.js";const u=JSON.parse('{"title":"Editor commands","description":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does.","frontmatter":{"title":"Editor commands","description":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/editor-commands.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/editor-commands.html"}],["meta",{"property":"og:title","content":"Editor commands | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does."}]]},"headers":[],"relativePath":"reference/editor-commands.md","filePath":"reference/editor-commands.md","lastUpdated":1794864119000}'),n={name:"reference/editor-commands.md"};function a(d,t,i,h,c,l){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="editor-commands" tabindex="-1">Editor commands <a class="header-anchor" href="#editor-commands" aria-label="Permalink to &quot;Editor commands&quot;">​</a></h1><p>Every command the two editors offer, by what it acts on. VS Code lists them in the command palette under <strong>Piwi:</strong>; a JetBrains IDE lists them under <strong>Tools → Piwi</strong> and in <strong>Find Action</strong>, says caret for cursor and project for window, and shows a toggle&#39;s state with a check mark. A row that names one editor is that editor&#39;s alone. Some commands have a shortcut in both editors (<a href="#keys">Keys</a>); a run&#39;s controls take the debugger&#39;s keys (<a href="/features/editor-run-control.html#the-controls">The controls</a>).</p><h3 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h3><p><code>Ctrl+Shift+Alt</code> with a letter, <code>Cmd</code> for <code>Ctrl</code> on macOS. Record here… and Run the test at the cursor act in an editor of a JavaScript or TypeScript file, the others there and in Piwi&#39;s views (the Piwi tool window in a JetBrains IDE), and nowhere else. A JetBrains keymap where that chord is another action&#39;s in those places takes the letter of its row, as do the keymaps descending from it. <strong>Settings → Keymap</strong> shows <code>$default</code> as Windows, <code>Mac OS X 10.5+</code> as macOS, <code>Mac OS X</code> as IntelliJ IDEA Classic, and <code>Default for XWin</code>, <code>Default for GNOME</code> and <code>Default for KDE</code> as XWin, GNOME and KDE; it drops <code> OSX</code> and <code> (Mac OS X)</code> from the other names, adding (macOS) on Windows and Linux.</p><table tabindex="0"><thead><tr><th>Keymap</th><th>Record here…, Stop recording</th><th>Re-run the failing tests</th><th>Run the test at the cursor</th><th>Open the failures</th></tr></thead><tbody><tr><td>VS Code, and <code>$default</code> and every JetBrains keymap not below</td><td><code>R</code></td><td><code>F</code></td><td><code>K</code></td><td><code>B</code></td></tr><tr><td><code>Default for XWin</code>, <code>Default for GNOME</code>, <code>Default for KDE</code></td><td><code>R</code></td><td><code>F</code></td><td><code>K</code></td><td><code>G</code></td></tr><tr><td><code>Mac OS X 10.5+</code>, <code>Eclipse (Mac OS X)</code>, <code>Sublime Text (Mac OS X)</code>, <code>VSCode OSX</code>, <code>macOS System Shortcuts</code></td><td><code>Z</code></td><td><code>F</code></td><td><code>K</code></td><td><code>B</code></td></tr><tr><td><code>Visual Studio</code>, <code>Visual Studio 2022</code>, <code>Visual Assist</code></td><td><code>G</code></td><td><code>F</code></td><td><code>J</code></td><td><code>B</code></td></tr><tr><td><code>ReSharper</code></td><td>none</td><td><code>T</code></td><td><code>J</code></td><td>none</td></tr><tr><td><code>Visual Studio OSX</code>, <code>Visual Assist OSX</code></td><td><code>Z</code></td><td><code>F</code></td><td><code>J</code></td><td><code>B</code></td></tr><tr><td><code>ReSharper OSX</code></td><td><code>Z</code></td><td><code>T</code></td><td><code>J</code></td><td><code>S</code></td></tr><tr><td><code>TextMate</code></td><td><code>R</code></td><td><code>J</code></td><td><code>K</code></td><td><code>B</code></td></tr></tbody></table><p>They share a key only with an action of the Database tool window or a database console&#39;s results, or of a Java, Kotlin script, Go or Terraform file. <strong>Preferences: Open Keyboard Shortcuts</strong> changes them in VS Code (search <code>piwi</code>), <strong>Settings → Keymap</strong> in a JetBrains IDE (search <code>Piwi</code>).</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Connect…</strong>, <strong>Piwi: Disconnect</strong></td><td>Choose the desktop app or an instance and its project, or forget them: <a href="/features/editor-connection.html">Editor connection</a></td></tr><tr><td><strong>Piwi: Open settings</strong></td><td>Piwi&#39;s settings: the instance and the project</td></tr><tr><td><strong>Piwi: Read the instance and the configs again</strong></td><td>Fetch the indexes and the latest run again and read the Playwright configs; in a JetBrains IDE, search the project for configs again and start a stopped editor service</td></tr><tr><td><strong>Piwi: Restart the editor service</strong></td><td>Stop the editor service and start it again</td></tr><tr><td><strong>Piwi: Open the log</strong></td><td>The editor service&#39;s log: its starts and ends, its errors and the requests that failed</td></tr><tr><td><strong>Piwi: Open the Piwi menu</strong></td><td>VS Code: the status bar item&#39;s menu, which a JetBrains IDE opens with a click on its item: <a href="/features/editor-status-bar.html">The editor&#39;s status bar</a></td></tr><tr><td><strong>Piwi: Node.js settings…</strong></td><td>JetBrains: choose the Node.js the editor service starts with</td></tr><tr><td><strong>Piwi: Get started</strong></td><td>Open the first steps: VS Code&#39;s walkthrough, or the Get started tab of the Piwi tool window in a JetBrains IDE</td></tr><tr><td><strong>Piwi: Open the documentation</strong></td><td>Open this site in the browser: <a href="/features/editors.html">Editor extensions</a> from VS Code, <a href="/features/jetbrains.html">JetBrains plugin</a> from a JetBrains IDE</td></tr></tbody></table><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Run the test at the cursor</strong></td><td>Run the test whose <code>test(…)</code> call holds the cursor: <a href="/features/editor-runs.html#run-tests">Run tests</a></td></tr><tr><td><strong>Piwi: Debug the test at the cursor</strong></td><td>Run it headed, at your <a href="/features/editor-breakpoints.html">breakpoints</a>, holding each failure at its line</td></tr><tr><td><strong>Piwi: Verify the test at the cursor ×3</strong></td><td>Run it three times without retries and say how many runs passed</td></tr><tr><td><strong>Piwi: Run this spec</strong></td><td>Run every test of the spec as it stands</td></tr><tr><td><strong>Piwi: Run the tests that reach this file</strong></td><td>Run the tests that reach the active file through <a href="/features/code-reach.html">code reach</a></td></tr><tr><td><strong>Piwi: Run a saved selection…</strong></td><td>Run a saved <a href="/features/test-selection.html">selection</a></td></tr><tr><td><strong>Piwi: Show the test&#39;s actions…</strong></td><td>VS Code: the actions of the test at the cursor, as its gutter offers them</td></tr><tr><td><strong>Piwi: Re-run the failing tests</strong></td><td>Run every test that still fails: <a href="/features/editor-runs.html#re-run-the-failing-tests">Re-run the failing tests</a></td></tr><tr><td><strong>Piwi: Turn headed runs on or off</strong></td><td>Run every test Piwi starts in this window headed, or headless: <a href="/features/editor-runs.html#how-a-run-starts">How a run starts</a></td></tr><tr><td><strong>Piwi: Hold failures from each run&#39;s start…</strong></td><td>Auto, On or Off: whether a failed test of each run waits at its line for an answer</td></tr><tr><td><strong>Piwi: Run options…</strong></td><td>Both options above in one list, with their choices now: a pick turns Run headed on or off, or opens Hold failures</td></tr></tbody></table><h2 id="the-failures-and-the-dashboard" tabindex="-1">The failures and the dashboard <a class="header-anchor" href="#the-failures-and-the-dashboard" aria-label="Permalink to &quot;The failures and the dashboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Refresh the latest run</strong></td><td>Read the latest run and its failures again, and none of the indexes</td></tr><tr><td><strong>Piwi: Open in dashboard</strong></td><td>Open the selected failure, run or test in the dashboard; from the palette, this file&#39;s test, else the latest run</td></tr><tr><td><strong>Piwi: Open the latest run</strong></td><td>Open the run the status bar shows</td></tr><tr><td><strong>Piwi: Compare with…</strong></td><td>Choose the run the failures are read against: <a href="/features/editor-status-bar.html#compare-with-another-run">Compare with another run</a></td></tr><tr><td><strong>Piwi: Group the failures by…</strong></td><td>File, cluster or owner, or a flat list: <a href="/features/editor-failures.html#the-failures-view">The failures view</a></td></tr><tr><td><strong>Piwi: Follow the active editor</strong>, <strong>Piwi: Stop following the active editor</strong></td><td>VS Code: select the active file&#39;s first failure in the failures view, or stop</td></tr><tr><td><strong>Piwi: Open the failures</strong></td><td>Open the failures view, the Piwi tool window&#39;s in a JetBrains IDE</td></tr><tr><td><strong>Piwi: Show the run&#39;s flaky tests</strong></td><td>Open the failures view on the run&#39;s <a href="/features/flaky-tests.html">flaky tests</a></td></tr><tr><td><strong>Piwi: Show or hide the coverage marks</strong></td><td>The <a href="/features/editor-coverage.html">coverage marks</a> of the lines the tests ran</td></tr></tbody></table><p>A failure&#39;s menu in the failures view adds <strong>Run with Piwi</strong>, <strong>Debug with Piwi</strong>, <strong>Verify ×3 with Piwi</strong>, <strong>Go to the test</strong>, <strong>Open the trace</strong>, <strong>Open the screenshot</strong>, <strong>Copy context for agent</strong>, <strong>Reproduce in the desktop app</strong>, <strong>Find the breaking commit in the desktop app</strong>, <strong>Run Flake Lab on its untested suspects in the desktop app</strong>, <strong>File an issue</strong> and, on a flaky test in VS Code, <strong>Look into this flake…</strong>: <a href="/features/editor-failures.html">Failures in the editor</a>.</p><h2 id="recording" tabindex="-1">Recording <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Recording&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Record here…</strong></td><td>Record at the cursor, in a browser your project&#39;s Playwright opens: <a href="/features/editor-recording.html">Record tests from the editor</a></td></tr><tr><td><strong>Piwi: Record a new test file…</strong></td><td>Create a spec and record into it; in a JetBrains IDE, the <strong>New</strong> menu&#39;s <strong>Playwright test (recorded)…</strong> too</td></tr><tr><td><strong>Piwi: Stop recording</strong>, <strong>Piwi: Pause recording</strong>, <strong>Piwi: Resume recording</strong></td><td>Control the recording in progress</td></tr><tr><td><strong>Piwi: Go to the recorded lines</strong></td><td>JetBrains: open the lines the recording in progress writes</td></tr><tr><td><strong>Piwi: Pair with Piwi Picker</strong></td><td>Copy the address <a href="/features/editor-recording.html#send-from-piwi-picker">Piwi Picker sends to</a></td></tr></tbody></table><h2 id="run-control" tabindex="-1">Run control <a class="header-anchor" href="#run-control" aria-label="Permalink to &quot;Run control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Pause the run</strong>, <strong>Piwi: Resume the run</strong>, <strong>Piwi: Step to the next call</strong>, <strong>Piwi: Run to the cursor</strong>, <strong>Piwi: Finish the test</strong>, <strong>Piwi: End the test</strong>, <strong>Piwi: Stop the run</strong></td><td><a href="/features/editor-run-control.html">Pause and step from the editor</a></td></tr><tr><td><strong>Piwi: Go to the stopped line</strong>, <strong>Piwi: Show the paused page</strong></td><td>Open the line a test is stopped at, or an image of its page</td></tr><tr><td><strong>Piwi: Turn hold failures on or off for the run</strong></td><td>Whether a failed test the pause bar does not show waits at its line, in this run</td></tr><tr><td><strong>Piwi: Watch a worker&#39;s test</strong>, <strong>Piwi: Pause and watch a worker&#39;s test</strong>, <strong>Piwi: Open the trace so far</strong></td><td><a href="/features/watch-running-test.html">Watch a local test</a></td></tr><tr><td><strong>Piwi: Show the stopped test&#39;s browser</strong></td><td>Bring a headed run&#39;s browser window to the front</td></tr><tr><td><strong>Piwi: Share the stopped test&#39;s browser with Playwright tools</strong></td><td><a href="/features/editor-run-control.html#share-with-playwright-tools">Share with Playwright tools</a></td></tr><tr><td><strong>Piwi: Open the page of a run of this window</strong></td><td>The page of a run this window started or follows, on the instance or the desktop app</td></tr><tr><td><strong>Piwi: Open the branch&#39;s run in progress</strong></td><td>VS Code: open the run of the branch the instance is receiving: <a href="/features/watch-a-run.html">Follow a run</a></td></tr></tbody></table><h3 id="where-the-run-controls-are" tabindex="-1">Where the run controls are <a class="header-anchor" href="#where-the-run-controls-are" aria-label="Permalink to &quot;Where the run controls are&quot;">​</a></h3><ul><li><strong>In VS Code</strong>: the Piwi item&#39;s menu while they apply, after <strong>Go to the stopped line</strong>; the command palette; the editor title, Pause or Resume, Step, Finish and Stop (on a run this window started) in the debug toolbar&#39;s order, the others under <code>…</code>; and, while a test is stopped, in the editor&#39;s context menu, right after its Go to entries, and on its worker&#39;s page (Resume, Step, Finish and Write code…).</li><li><strong>In a JetBrains IDE</strong>: <strong>Tools → Piwi</strong> and the <strong>Run</strong> menu, enabled while they apply; the toolbar of the run&#39;s Run tab, acting on that run; the status bar item&#39;s menu; and, while a test is stopped, first in the editor&#39;s context menu, and on its worker&#39;s tab (Resume, Step, Finish and Write code…).</li></ul><p>A run is named after what it runs (<code>checkout.spec.ts:12</code>, <code>a.spec.ts and 2 more</code>, the title it greps, <code>×3</code> after a Verify ×3, a Flake Lab line&#39;s command), in its terminal or Run tab and wherever you pick it, where it also has its number on the instance once it has one (<code>Run #78 · checkout.spec.ts:12</code>). Two runs of one name show their refs.</p><h2 id="code-at-a-stop" tabindex="-1">Code at a stop <a class="header-anchor" href="#code-at-a-stop" aria-label="Permalink to &quot;Code at a stop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Pick a locator at the stop</strong>, <strong>Piwi: Record at the stop</strong>, <strong>Piwi: Assert at the stop</strong>, <strong>Piwi: Assert a region at the stop</strong>, <strong>Piwi: Mock a request at the stop…</strong></td><td>What the stop&#39;s own controls call Pick a locator, Record, Assert, Assert a region and Mock a request: <a href="/features/editor-stop-code.html">Code from a pause</a></td></tr><tr><td><strong>Piwi: Write code at the stop…</strong></td><td>VS Code: choose one of them</td></tr></tbody></table><h2 id="share-live" tabindex="-1">Share live <a class="header-anchor" href="#share-live" aria-label="Permalink to &quot;Share live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Share the run live on the team instance</strong>, <strong>Piwi: Stop sharing the run live</strong></td><td><a href="/features/share-live.html">Share a local run live</a></td></tr><tr><td><strong>Piwi: Share this window&#39;s runs live until I stop</strong>, <strong>Piwi: Stop sharing this window&#39;s runs live</strong></td><td>Every run of this window, from now on</td></tr><tr><td><strong>Piwi: Shared live: open the run page, copy its link or stop sharing…</strong></td><td>VS Code: the menu of the status bar&#39;s live item</td></tr></tbody></table><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Copy the MCP server configuration…</strong></td><td>Piwi&#39;s <a href="/features/editors.html#piwi-s-mcp-server-for-the-agent">MCP server</a> for an agent</td></tr><tr><td><strong>Piwi: Copy the runs&#39; MCP server configuration for agents…</strong>, <strong>Piwi: Copy the runs&#39; MCP server configuration for Claude Code or Cursor</strong>, <strong>Piwi: Reset the runs&#39; MCP server token</strong></td><td><a href="/features/agent-run-control.html">Run control for agents</a>; the second is JetBrains&#39;</td></tr></tbody></table><p>The lines above the code and the quick fixes also run commands no menu lists: <strong>Run tests</strong>, <strong>Run a command</strong>, <strong>Copy text</strong> and <strong>Reproduce, bisect or run Flake Lab in the desktop app</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/editors.html">Editor extensions</a>: what the extensions show, and how they connect.</li><li><a href="/features/jetbrains.html">JetBrains plugin</a>: what the plugin needs and draws differently.</li></ul>',29)])])}const f=e(n,[["render",a]]);export{u as __pageData,f as default};
